export type FocusKey = keyof typeof copy;
export function useFocusText() {
  const { lang } = useI18n();
  const index = { de: 0, en: 1, es: 2 }[lang];
  const t = (key: FocusKey, values: Record<string, string | number> = {}) =>
    copy[key][index].replace(/\{(\w+)\}/g, (match, name) => String(values[name] ?? match));
  const number = (value: number) => value.toLocaleString(lang, { maximumFractionDigits: value > 0 && value < 1 ? 4 : 2 });
  const date = (value: string, weekday = false) => new Date(value.slice(0, 10) + "T12:00:00Z").toLocaleDateString(lang, weekday ? { weekday: "short", timeZone: "UTC" } : { day: "numeric", month: "short", timeZone: "UTC" });
  return { t, number, date, lang };
}
